{"security_risk":"LOW","summary":"Print all operation metadata","command":"cat /tmp/contract_compact.json | python3 -c "
import json,sys
c=json.load(sys.stdin)
# print all operations with operationId, request body, responses
for p, methods in c['paths'].items():
    for m, op in methods.items():
        print('====================================')
        print(f'{m.upper()} {p}  -> {op[\"operationId\"]}')
        if op.get('parameters'):
            print('  params:', json.dumps(op['parameters']))
        if op.get('requestBody'):
            rb = op['requestBody']
            if 'content' in rb:
                for ct, v in rb['content'].items():
                    print(f'  request {ct}:', json.dumps(v.get('schema')))
        resp_codes = sorted(op['responses'].keys())
        print(f'  responses: {resp_codes}')
