	s.mu.Lock()
	defer s.mu.Unlock()
	if st.ID == uuid.Nil {
		st.ID = uuid.New()
	}
	if st.IncompatibleSampleTypes == nil {
		st.IncompatibleSampleTypes = []uuid.UUID{}
	}
	s.sampleTypes[st.ID] = st
	s.sampleTypesByName[st.Name] = st
	return s.persistSampleType(st)
}

