	_, err := pool.Exec(ctx, migrationsSQL)
	if err != nil {
		return fmt.Errorf("migrations: %w", err)
	}
	return nil
}

// RecreateSchema drops and recreates all tables. Used by reset.
func RecreateSchema(ctx context.Context, pool *pgxpool.Pool) error {
	tables := []string{
		"serviceability_versions", "capacity_reservations", "handoffs", "assignments",
		"journey_plans", "samples", "collection_requests", "lab_acceptances",
		"connections", "locations", "sample_types", "users",
	}
	for _, t := range tables {
		if _, err := pool.Exec(ctx, fmt.Sprintf("DROP TABLE IF EXISTS %s CASCADE", t)); err != nil {
			return fmt.Errorf("drop %s: %w", t, err)
		}
	}
	return RunMigrations(ctx, pool)
}

func WipeAll(ctx context.Context, pool *pgxpool.Pool) error {
