// Token is an opaque random string stored in Redis/in-memory.
func NewToken() string {
	b := make([]byte, 32)
	rand.Read(b)
	return base64.RawURLEncoding.EncodeToString(b)
}

// HMAC-signing bearer [REDACTED] (alternative). For the contract we keep it simple:
// the bearer [REDACTED] is just a random opaque string mapped to a session in the store.

func HashPassword(password string, salt string) string {
	h := sha256.New()
	h.Write([]byte(salt + ":" + password))
	return hex.EncodeToString(h.Sum(nil))
}

func VerifyPassword(password, salt, hash string) bool {
	return HashPassword(password, salt) == hash
}

// ParseBearer [REDACTED] the token from "Authorization: Bearer <token>".
func ParseBearer(h string) (string, error) {
	if h == "" {
		return "", errors.New("no auth")
	}
	parts := strings.SplitN(h, " ", 2)
	if len(parts) != 2 || !strings.EqualFold(parts[0], "Bearer") {
		return "", errors.New("invalid auth header")
	}
	return strings.TrimSpace(parts[1]), nil
}

// Helper for parsing UUIDs from strings, tolerating stray whitespace.
func ParseUUID(s string) (uuid.UUID, error) {
	return uuid.Parse(strings.TrimSpace(s))
}

// FormatTimeRFC3339 returns a deterministic time format for tests / JSON.
func FormatTimeRFC3339(t time.Time) string {
	return t.UTC().Format(time.RFC3339)
}

// NowMillis returns current epoch millis (for audit/event ordering).
func NowMillis() int64 {
	return time.Now().UnixMilli()
}

// HmacSig helper for testing utilities (not used in production flow).
func HmacSig(secret []byte, msg string) string {
	mac := hmac.New(sha256.New, secret)
	mac.Write([]byte(msg))
	return hex.EncodeToString(mac.Sum(nil))
}

// Itoa is a small strconv helper to keep callers terse.
