{"security_risk":"LOW","summary":"Create realtime hub","command":"create","path":"/workspace/internal/realtime/hub.go","file_text":"package realtime

import (
	"sync"

	"github.com/gorilla/websocket"
)

type Client struct {
	UserID string
	Conn   *websocket.Conn
	Send   chan []byte
	mu     sync.Mutex
}

func (c *Client) WriteJSON(v any) error {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.Conn.WriteJSON(v)
}

type Hub struct {
	mu      sync.RWMutex
	clients map[*Client]struct{}
}

func NewHub() *Hub { return &Hub{clients: make(map[*Client]struct{})} }

func (h *Hub) Add(c *Client) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.clients[c] = struct{}{}
}

func (h *Hub) Remove(c *Client) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if _, ok := h.clients[c]; ok {
		delete(h.clients, c)
		close(c.Send)
	}
}

func (h *Hub) Broadcast(payload []byte) {
	h.mu.RLock()
	defer h.mu.RUnlock()
	for c := range h.clients {
		select {
		case c.Send <- payload:
		default:
		}
	}
}

func (h *Hub) Count() int {
	h.mu.RLock()
	defer h.mu.RUnlock()
	return len(h.clients)
}"}

{"security_risk":"LOW","summary":"Create serviceability package","command":"create","path":"/workspace/internal/serviceability/serviceability.go","file_text":"package serviceability

import (
	"context"
	"encoding/json"
	"fmt"
	"math"
	"sync"
	"time"

	"arena.local/lab/internal/domain"
	"arena.local/lab/internal/store"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgxpool"
)

type Serviceability struct {
	mu      sync.RWMutex
	pg      *pgxpool.Pool
	st      *store.Store
	current *Snapshot
	regions []Region
	activeCollectionPoints int
	networkRevision        int64
}

type Region struct {
	CenterLat float64 `json:"centerLat"`
	CenterLng float64 `json:"centerLng"`
	RadiusKm  float64 `json:"radiusKm"`
	NodeID    uuid.UUID `json:"nodeId"`
	NodeName  string    `json:"nodeName"`
}

type Snapshot struct {
	Version       int       `json:"version"`
	Status        string    `json:"status"`
	ComputedAt    time.Time `json:"computedAt"`
	NetworkRev    int64     `json:"networkRevision"`
	Regions       []Region  `json:"regions"`
	ActiveCP      int       `json:"activeCollectionPointCount"`
}

type Result struct {
	Serviceable         bool      `json:"serviceable"`
	Reason              string    `json:"reason"`
	TargetLaboratoryID  *uuid.UUID `json:"targetLaboratoryId,omitempty"`
	EstimatedArrivalAt  *time.Time `json:"estimatedArrivalAt,omitempty"`
	ServiceabilityVersion int     `json:"serviceabilityVersion"`
}

func New(pg *pgxpool.Pool, st *store.Store) *Serviceability {
	s := &Serviceability{pg: pg, st: st}
	s.recompute()
	s.serve()
	return s
}

func (s *Serviceability) serve() {
	if s.pg != nil {
		row := s.pg.QueryRow(context.Background(),
			`SELECT version, computed_at, network_revision, data FROM serviceability_versions ORDER BY version DESC LIMIT 1`)
		var ver int
		var computedAt time.Time
		var netRev int64
		var dataJSON []byte
		if err := row.Scan(&ver, &computedAt, &netRev, &dataJSON); err == nil {
			snap := &Snapshot{Version: ver, Status: "complete", ComputedAt: computedAt, NetworkRev: netRev}
			json.Unmarshal(dataJSON, &snap.Regions)
			snap.ActiveCP = len(snap.Regions)
			s.mu.Lock()
			s.current = snap
			s.regions = snap.Regions
			s.activeCollectionPoints = snap.ActiveCP
			s.networkRevision = netRev
			s.mu.Unlock()
		}
	}
}

func (s *Serviceability) Recompute() {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.recompute()
	s.persistLocked()
}

func (s *Serviceability) recompute() {
	locs := s.st.AllLocations()
	conns := s.st.AllConnections()
	accepts := []domain.LabAcceptance{}
	for _, l := range locs {
		if l.IsLaboratory && l.Active && l.Functions.Laboratory {
			_ = conns
			// collect acceptance info indirectly via store iteration
		}
	}
	// Build regions: a "region" is a 5km serviceability area centered at each active collection point
	regions := []Region{}
	cpCount := 0
	for _, l := range locs {
		if !l.Active {
			continue
		}
		if l.Functions.CollectionPoint {
			cpCount++
			regions = append(regions, Region{
				CenterLat: l.Latitude,
				CenterLng: l.Longitude,
				RadiusKm:  5.0,
				NodeID:    l.ID,
				NodeName:  l.Name,
			})
		}
	}
	s.regions = regions
	s.activeCollectionPoints = cpCount
	if s.current == nil {
		s.current = &Snapshot{
			Version:    1,
			Status:     "complete",
			ComputedAt: time.Now(),
			NetworkRev: 1,
		}
	} else {
		s.current.Version++
		s.current.ComputedAt = time.Now()
		s.current.NetworkRev++
	}
	s.current.Regions = regions
	s.current.ActiveCP = cpCount
	s.networkRevision = s.current.NetworkRev
}

func (s *Serviceability) persistLocked() {
	if s.pg == nil || s.current == nil {
		return
	}
	dataJSON, _ := json.Marshal(s.current.Regions)
	_, _ = s.pg.Exec(context.Background(),
		`INSERT INTO serviceability_versions(version, computed_at, network_revision, data) VALUES ($1,$2,$3,$4)
		 ON CONFLICT (version) DO UPDATE SET data=EXCLUDED.data`,
		s.current.Version, s.current.ComputedAt, s.current.NetworkRev, dataJSON)
}

func (s *Serviceability) Snapshot() Snapshot {
	s.mu.RLock()
	defer s.mu.RUnlock()
	if s.current == nil {
		return Snapshot{Version: 1, Status: "complete", ComputedAt: time.Now(), NetworkRev: 0, Regions: []Region{}, ActiveCP: 0}
	}
	return *s.current
}

func (s *Serviceability) Check(origin domain.Coordinate, originType string, originNodeID *uuid.UUID, sampleTypeID uuid.UUID, deadline time.Time, earliest, latest *time.Time) Result {
	s.mu.RLock()
	snap := s.current
	regions := s.regions
	s.mu.RUnlock()

	if snap == nil {
		return Result{Serviceable: false, Reason: "no_route", ServiceabilityVersion: 1}
	}

	// Step 1: is origin within 5km of an active collection point?
	nearestNodeID, ok := nearestCollectionNode(origin, regions)
	if !ok && originType != "node" && originType != "clinic" {
		return Result{Serviceable: false, Reason: "outside_service_coverage", ServiceabilityVersion: snap.Version}
	}
	if originType == "node" || originType == "clinic" {
		if originNodeID == nil {
			return Result{Serviceable: false, Reason: "invalid_origin_type", ServiceabilityVersion: snap.Version}
		}
		nearestNodeID = *originNodeID
	}

	// Step 2: is there an active lab that accepts the sample type?
	labID, travelMinutes, ok := findAcceptingLab(s.st, sampleTypeID, nearestNodeID, deadline)
	if !ok {
		return Result{Serviceable: false, Reason: "no_accepting_laboratory", ServiceabilityVersion: snap.Version}
	}

	// Step 3: capacity available (we use the total minus reservations)
	if !capacityAvailable(s.st, labID) {
		return Result{Serviceable: false, Reason: "insufficient_capacity", ServiceabilityVersion: snap.Version}
	}

	// Step 4: deadline reachable
	arrival := time.Now().Add(time.Duration(travelMinutes) * time.Minute)
	if arrival.After(deadline) {
		return Result{Serviceable: false, Reason: "deadline_unreachable", ServiceabilityVersion: snap.Version}
	}

	// Step 5: handling rules satisfiable
	st, ok := s.st.GetSampleType(sampleTypeID)
	if !ok {
		return Result{Serviceable: false, Reason: "handling_rules_unsatisfiable", ServiceabilityVersion: snap.Version}
	}
	if st.RequiresCooledRoute && !cooledRouteAvailable(s.st, nearestNodeID, labID) {
		return Result{Serviceable: false, Reason: "handling_rules_unsatisfiable", ServiceabilityVersion: snap.Version}
	}

	return Result{
		Serviceable:         true,
		Reason:              "serviceable",
		TargetLaboratoryID:  &labID,
		EstimatedArrivalAt:  &arrival,
		ServiceabilityVersion: snap.Version,
	}
}

func nearestCollectionNode(c domain.Coordinate, regions []Region) (uuid.UUID, bool) {
	var best uuid.UUID
	bestDist := math.MaxFloat64
	found := false
	for _, r := range regions {
		d := haversineKm(c.Latitude, c.Longitude, r.CenterLat, r.CenterLng)
		if d <= r.RadiusKm && d < bestDist {
			best = r.NodeID
			bestDist = d
			found = true
		}
	}
	return best, found
}

func haversineKm(lat1, lng1, lat2, lng2 float64) float64 {
	const R = 6371.0
	rad := math.Pi / 180.0
	dlat := (lat2 - lat1) * rad
	dlng := (lng2 - lng1) * rad
	a := math.Sin(dlat/2)*math.Sin(dlat/2) +
		math.Cos(lat1*rad)*math.Cos(lat2*rad)*
			math.Sin(dlng/2)*math.Sin(dlng/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}

func findAcceptingLab(st *store.Store, sampleTypeID, fromNode uuid.UUID, deadline time.Time) (uuid.UUID, int, bool) {
	locs := st.AllLocations()
	conns := st.AllConnections()
	bestLab := uuid.Nil
	bestTime := math.MaxInt32
	for _, l := range locs {
		if !l.IsLaboratory || !l.Active || !l.Functions.Laboratory {
			continue
		}
		acc, ok := st.GetAcceptance(l.ID, sampleTypeID)
		if !ok || !acc.Accepts {
			continue
		}
		t := shortestPathMinutes(fromNode, l.ID, conns)
		if t < 0 {
			continue
		}
		if t < bestTime {
			bestTime = t
			bestLab = l.ID
		}
	}
	if bestLab == uuid.Nil {
		return uuid.Nil, 0, false
	}
	return bestLab, bestTime, true
}

func shortestPathMinutes(from, to uuid.UUID, conns []*domain.Connection) int {
	if from == to {
		return 0
	}
	// BFS
	dist := map[uuid.UUID]int{from: 0}
	queue := []uuid.UUID{from}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		if cur == to {
			return dist[cur]
		}
		for _, c := range conns {
			if !c.Active || c.FromLocationID != cur {
				continue
			}
			if _, seen := dist[c.ToLocationID]; !seen {
				dist[c.ToLocationID] = dist[cur] + c.TravelMinutes
				queue = append(queue, c.ToLocationID)
			}
		}
	}
	return -1
}

func capacityAvailable(st *store.Store, resourceID uuid.UUID) bool {
	l, ok := st.GetLocation(resourceID)
	if !ok {
		return true
	}
	return l.Capacity.RegularReserved < l.Capacity.RegularUnits
}

func cooledRouteAvailable(st *store.Store, from, to uuid.UUID) bool {
	conns := st.AllConnections()
	queue := []uuid.UUID{from}
	seen := map[uuid.UUID]bool{from: true}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		if cur == to {
			return true
		}
		for _, c := range conns {
			if !c.Active || c.Cooled || c.FromLocationID != cur {
				continue
			}
			if !seen[c.ToLocationID] {
				seen[c.ToLocationID] = true
				queue = append(queue, c.ToLocationID)
			}
		}
	}
	return false
}

