func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Access-Control-Allow-Origin", "*")
	w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type, Idempotency-Key")
	w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS, PATCH")
	if r.Method == http.MethodOptions {
		w.WriteHeader(http.StatusNoContent)
		return
	}
	s.mux.ServeHTTP(w, r)
}

// ---------- Error helper ----------

func WriteError(w http.ResponseWriter, status int, code, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(map[string]any{"error": msg, "code": code})
}

func WriteJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

// ---------- Auth helpers ----------

type ctxKey int

const userKey ctxKey = 0

func (s *Server) authenticate(r *http.Request) (*domain.User, error) {
	tok, err := auth.ParseBearer(r.Header.Get("Authorization"))
	if err != nil {
		return nil, err
	}
	uid, ok := s.st.GetSession(tok)
	if !ok {
		return nil, errors.New("invalid token")
	}
	u, ok := s.st.GetUser(uid)
	if !ok {
		return nil, errors.New("user gone")
	}
	return u, nil
}

func (s *Server) requireAuth(fn http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		u, err := s.authenticate(r)
		if err != nil {
			WriteError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
			return
		}
		ctx := context.WithValue(r.Context(), userKey, u)
		fn(w, r.WithContext(ctx))
	}
}

func currentUser(r *http.Request) *domain.User {
	u, _ := r.Context().Value(userKey).(*domain.User)
	return u
}

// ---------- Ready ----------

func (s *Server) handleReady(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	// Verify datastores
	ctx, cancel := context.WithTimeout(r.Context(), 5*time.Second)
	defer cancel()
	ok := true
	if s.rdb != nil {
		if err := s.rdb.Ping(ctx).Err(); err != nil {
			ok = false
		}
	}
	if ok {
		w.WriteHeader(http.StatusOK)
		w.Write([]byte(`{"status":"ready"}`))
	} else {
		w.WriteHeader(http.StatusServiceUnavailable)
		w.Write([]byte(`{"status":"unready"}`))
	}
}

// ---------- Events (WebSocket) ----------

func (s *Server) handleEvents(w http.ResponseWriter, r *http.Request) {
	c, err := s.upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	// Optional auth: token can be passed via query
	var uid uuid.UUID
	if tok := r.URL.Query().Get("token"); tok != "" {
		if u, ok := s.st.GetSession(tok); ok {
			uid = u
		}
	}
	client := &realtime.Client{
		UserID: uid.String(),
		Conn:   c,
		Send:   make(chan []byte, 256),
	}
	s.hub.Add(client)
	defer s.hub.Remove(client)

	// Send existing events from cursor
	cursorStr := r.URL.Query().Get("cursor")
	var cursor int64
	fmt.Sscanf(cursorStr, "%d", &cursor)
	events, maxID := s.st.GetEventsSince(cursor)
	for _, ev := range events {
		b, _ := json.Marshal(ev)
		c.WriteMessage(websocket.TextMessage, b)
	}
	cursor = maxID

	// Reader loop
	go func() {
		for {
			_, _, err := c.ReadMessage()
			if err != nil {
				return
			}
		}
	}()

	// Writer loop
	ticker := time.NewTicker(2 * time.Second)
	defer ticker.Stop()
	for {
		select {
		case msg, ok := <-client.Send:
			if !ok {
				return
			}
			if err := c.WriteMessage(websocket.TextMessage, msg); err != nil {
				return
			}
		case <-ticker.C:
			// Heartbeat
			if err := c.WriteMessage(websocket.TextMessage, []byte(`{"type":"ping"}`)); err != nil {
				return
			}
			// poll events since last cursor
			events, maxID := s.st.GetEventsSince(cursor)
			for _, ev := range events {
				b, _ := json.Marshal(ev)
				c.WriteMessage(websocket.TextMessage, b)
			}
			cursor = maxID
		}
	}
}

// ---------- JSON body helper ----------

func ReadJSON(r *http.Request, v any) error {
	body, err := io.ReadAll(r.Body)
	if err != nil {
		return err
	}
	if len(body) == 0 {
		return errors.New("empty body")
	}
	return json.Unmarshal(body, v)
}

// JSON response wrapper
func OK(w http.ResponseWriter, data any) {
	WriteJSON(w, http.StatusOK, map[string]any{"data": data})
}

func Created(w http.ResponseWriter, data any) {
	WriteJSON(w, http.StatusCreated, map[string]any{"data": data})
}

// Audit helper
func (s *Server) audit(actor *domain.User, action, entityType, entityID string, success bool, outcome string, changes any) {
	if actor == nil {
		actor = &domain.User{ID: uuid.Nil, Username: "system"}
	}
	e := domain.AuditEntry{
		ID:            uuid.NewString(),
		ActorID:       actor.ID.String(),
		ActorUsername: actor.Username,
		Role:          actor.ActiveRole,
		Action:        action,
		EntityType:    entityType,
		EntityID:      entityID,
		Outcome:       outcome,
		Success:       success,
		Changes:       changes,
		Timestamp:     time.Now(),
	}
	_ = s.st.AppendAudit(e)
}

// Make the JWT secret rotatable via env if provided
func (s *Server) Secret() []byte {
	return s.jwtSecret
}

func HasRole(u *domain.User, role string) bool {
	for _, r := range u.Roles {
		if strings.EqualFold(r, role) {
			return true
		}
	}
	return false
}

func HasAnyRole(u *domain.User, roles ...string) bool {
	for _, role := range roles {
		if HasRole(u, role) {
			return true
		}
	}
	return false
}

func (s *Server) Mux() *http.ServeMux { return s.mux }

var _ = log.Print"}

{"security_risk":"LOW","summary":"Create auth_handlers.go","command":"create","path":"/workspace/internal/api/auth_handlers.go","file_text":"package api

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"net/http"
	"strings"
	"time"

	"arena.local/lab/internal/auth"
	"arena.local/lab/internal/domain"

	"github.com/google/uuid"
)

func (s *Server) handleLogin(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	if req.Username == "" || req.Password == "" {
		WriteError(w, http.StatusBadRequest, "invalid_credentials", "username and password required")
		return
	}
	u, ok := s.st.GetUserByName(strings.TrimSpace(strings.ToLower(req.Username)))
	if !ok {
		// Also try raw username
		u, ok = s.st.GetUserByName(strings.TrimSpace(req.Username))
	}
	if !ok {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Invalid credentials")
		s.audit(nil, "login", "user", req.Username, false, "user_not_found", nil)
		return
	}
	salt := u.Username
	if !auth.VerifyPassword(req.Password, salt, u.PasswordHash) {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Invalid credentials")
		s.audit(u, "login", "user", u.ID.String(), false, "bad_password", nil)
		return
	}
	if !u.Active {
		WriteError(w, http.StatusForbidden, "forbidden", "Account inactive")
		return
	}
	tok := auth.NewToken()
	s.st.PutSession(tok, u.ID)
	s.audit(u, "login", "user", u.ID.String(), true, "success", nil)
	s.st.AppendEvent("user.signed_in", map[string]interface{}{"userId": u.ID.String(), "username": u.Username})

	OK(w, map[string]any{
		"token":      tok,
		"user":       u,
		"activeRole": u.ActiveRole,
		"roles":      u.Roles,
	})
}

func (s *Server) handleLogout(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	tok, _ := auth.ParseBearer(r.Header.Get("Authorization"))
	if tok != "" {
		s.st.DeleteSession(tok)
	}
	if u != nil {
		s.audit(u, "logout", "user", u.ID.String(), true, "success", nil)
		s.st.AppendEvent("user.signed_out", map[string]interface{}{"userId": u.ID.String()})
	}
	OK(w, map[string]any{"ok": true})
}

func (s *Server) handleSelectActiveRole(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	var req struct {
		Role string `json:"role"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	if !HasRole(u, req.Role) {
		WriteError(w, http.StatusForbidden, "forbidden", "role not assigned")
		return
	}
	prev := u.ActiveRole
	u.ActiveRole = req.Role
	if err := s.st.UpdateUser(u); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save failed")
		return
	}
	s.audit(u, "select_active_role", "user", u.ID.String(), true, "role_switched", map[string]any{"from": prev, "to": req.Role})
	OK(w, map[string]any{"activeRole": req.Role, "user": u})
}

func (s *Server) handleReadUser(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Query().Get("userId")
	if idStr == "" {
		u := currentUser(r)
		if u == nil {
			WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
			return
		}
		OK(w, u)
		return
	}
	uid, err := uuid.Parse(idStr)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_id", "invalid userId")
		return
	}
	u, ok := s.st.GetUser(uid)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "user not found")
		return
	}
	caller := currentUser(r)
	if caller == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	if caller.ID != u.ID && !HasAnyRole(caller, "administrator", "dispatcher") {
		WriteError(w, http.StatusForbidden, "forbidden", "cannot read other user")
		return
	}
	OK(w, u)
}

func (s *Server) handleListUsers(w http.ResponseWriter, r *http.Request) {
	caller := currentUser(r)
	if caller == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	if !HasAnyRole(caller, "administrator", "dispatcher") {
		WriteError(w, http.StatusForbidden, "forbidden", "list users requires admin/dispatcher")
		return
	}
	OK(w, s.st.ListUsers())
}

func (s *Server) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	caller := currentUser(r)
	if caller == nil || !HasRole(caller, "administrator") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin only")
		return
	}
	var req struct {
		Username    string   `json:"username"`
		Password    string   `json:"password"`
		Email       string   `json:"email"`
		FullName    string   `json:"fullName"`
		Phone       string   `json:"phone"`
		Roles       []string `json:"roles"`
		AssignedLocationID    *uuid.UUID `json:"assignedLocationId"`
		AssignedLaboratoryID  *uuid.UUID `json:"assignedLaboratoryId"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	if req.Username == "" || req.Password == "" {
		WriteError(w, http.StatusBadRequest, "invalid_input", "username and password required")
		return
	}
	if len(req.Roles) == 0 {
		WriteError(w, http.StatusBadRequest, "invalid_input", "at least one role required")
		return
	}
	if _, exists := s.st.GetUserByName(req.Username); exists {
		WriteError(w, http.StatusConflict, "conflict", "username exists")
		return
	}
	salt := randomSalt()
	u := &domain.User{
		ID:          uuid.New(),
		Username:    req.Username,
		Email:       req.Email,
		FullName:    req.FullName,
		Phone:       req.Phone,
		Roles:       req.Roles,
		Active:      true,
		PasswordHash: auth.HashPassword(req.Password, salt),
		AssignedLocationID:   req.AssignedLocationID,
		AssignedLaboratoryID: req.AssignedLaboratoryID,
		Available:  true,
		ActiveRole: req.Roles[0],
	}
	if err := s.st.CreateUser(u); err != nil {
		WriteError(w, http.StatusConflict, "conflict", err.Error())
		return
	}
	s.audit(caller, "create_user", "user", u.ID.String(), true, "success", map[string]any{"username": u.Username, "roles": u.Roles})
	s.st.AppendEvent("user.created", map[string]interface{}{"userId": u.ID.String(), "username": u.Username})
	Created(w, u)
}

func randomSalt() string {
	b := make([]byte, 8)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func (s *Server) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	caller := currentUser(r)
	if caller == nil || !HasRole(caller, "administrator") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin only")
		return
	}
	var req struct {
		UserID  string `json:"userId"`
		Active  *bool  `json:"active"`
		Password string `json:"password"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
