func (s *Server) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	caller := currentUser(r)
	if caller == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	var req struct {
		ResourceType string    `json:"resourceType"`
		ResourceID   uuid.UUID `json:"resourceId"`
		RegularUnits *int      `json:"regularUnits,omitempty"`
		CooledUnits  *int      `json:"cooledUnits,omitempty"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	if req.ResourceType != "location" && req.ResourceType != "connection" {
		WriteError(w, http.StatusBadRequest, "invalid_input", "resourceType must be location or connection")
		return
	}

	var (
		ownerOK bool
		resourceName string
	)
	if req.ResourceType == "location" {
		l, ok := s.st.GetLocation(req.ResourceID)
		if !ok {
			WriteError(w, http.StatusNotFound, "not_found", "location not found")
			return
		}
		ownerOK = HasRole(caller, "administrator") ||
			(HasRole(caller, "node_handler") && caller.AssignedLocationID != nil && *caller.AssignedLocationID == req.ResourceID) ||
			(HasRole(caller, "laboratory_intake_operator") && caller.AssignedLaboratoryID != nil && *caller.AssignedLaboratoryID == req.ResourceID)
		if !ownerOK {
			WriteError(w, http.StatusForbidden, "forbidden", "not authorized for this location")
			return
		}
		resourceName = l.Name
		if req.RegularUnits != nil {
			if *req.RegularUnits < l.Capacity.RegularReserved {
