// ---------- Serviceability check ----------

func (s *Server) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	caller := currentUser(r)
	if caller == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	var req struct {
		Origin             domain.Coordinate `json:"origin"`
		OriginType         string            `json:"originType"`
		OriginNodeID       *uuid.UUID        `json:"originNodeId"`
		SampleTypeID       uuid.UUID         `json:"sampleTypeId"`
		RequestedAt        time.Time         `json:"requestedAt"`
		DeliveryDeadline   time.Time         `json:"deliveryDeadline"`
		EarliestCollection *time.Time        `json:"earliestCollectionAt"`
		LatestCollection   *time.Time        `json:"latestCollectionAt"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	if req.DeliveryDeadline.IsZero() {
		WriteError(w, http.StatusBadRequest, "invalid_deadline", "deadline required")
		return
	}
	if req.RequestedAt.IsZero() {
		req.RequestedAt = time.Now()
	}
	if req.OriginType == "" {
		req.OriginType = "home"
	}
	if req.OriginType != "home" && req.OriginType != "clinic" && req.OriginType != "node" {
		WriteError(w, http.StatusBadRequest, "invalid_origin_type", "invalid origin type")
		return
	}
	earliest := time.Now()
	latest := req.DeliveryDeadline
	if req.EarliestCollection != nil {
		earliest = *req.EarliestCollection
	}
	if req.LatestCollection != nil {
		latest = *req.LatestCollection
	}
	if !latest.After(earliest) {
		WriteError(w, http.StatusBadRequest, "invalid_collection_window", "latest must be after earliest")
		return
	}
	if !req.DeliveryDeadline.After(earliest) {
		WriteError(w, http.StatusBadRequest, "invalid_deadline", "deadline must be after collection window start")
		return
	}
	res := s.svc.Check(req.Origin, req.OriginType, req.OriginNodeID, req.SampleTypeID, req.DeliveryDeadline, &earliest, &latest)
	// Audit but do NOT create any resource
	s.audit(caller, "check_serviceability", "serviceability", "", res.Serviceable, res.Reason, map[string]any{
		"sampleTypeId": req.SampleTypeID.String(),
		"serviceable":  res.Serviceable,
		"reason":       res.Reason,
	})
	OK(w, res)
}

