// ---------- List role work ----------

func (s *Server) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	role := r.URL.Query().Get("role")
	if role == "" {
		role = u.ActiveRole
	}
	out := map[string]interface{}{}

	switch role {
	case "certified_collection_professional":
		// Show pending offers for collection work
		offers := []*domain.Assignment{}
		all := s.st.ListAssignments()
		for _, a := range all {
			if a.WorkerRole != "certified_collection_professional" {
				continue
			}
			if a.WorkerID == nil || *a.WorkerID == u.ID {
				if a.Status == "offered" || a.Status == "pending" || a.Status == "accepted" {
					if a.WorkerID == nil || *a.WorkerID == u.ID {
						offers = append(offers, a)
					}
				}
			}
		}
		// Also include samples this user currently holds
		samples := []*domain.Sample{}
		for _, smp := range s.st.AllSamples() {
			if smp.CurrentHolderID != nil && *smp.CurrentHolderID == u.ID {
				samples = append(samples, smp)
			}
		}
		out["assignments"] = offers
		out["samples"] = samples
	case "relay_courier":
		offers := []*domain.Assignment{}
		for _, a := range s.st.ListAssignments() {
			if a.WorkerRole != "relay_courier" {
				continue
			}
			if a.Status == "offered" || a.Status == "pending" || a.Status == "accepted" || a.Status == "in_progress" {
				if a.WorkerID == nil || (a.WorkerID != nil && *a.WorkerID == u.ID) {
					offers = append(offers, a)
				}
			}
		}
		out["assignments"] = offers
	case "node_handler":
		offers := []*domain.Assignment{}
		for _, a := range s.st.ListAssignments() {
			if a.WorkerRole != "node_handler" {
				continue
			}
			if a.Status == "offered" || a.Status == "pending" || a.Status == "accepted" || a.Status == "in_progress" {
				if u.AssignedLocationID != nil && a.FromLocationID == *u.AssignedLocationID || a.ToLocationID == *u.AssignedLocationID {
					if a.WorkerID == nil || (a.WorkerID != nil && *a.WorkerID == u.ID) {
						offers = append(offers, a)
					}
				}
			}
		}
		out["assignments"] = offers
	case "laboratory_intake_operator":
		offers := []*domain.Assignment{}
		for _, a := range s.st.ListAssignments() {
			if a.WorkerRole != "laboratory_intake_operator" {
				continue
			}
			if a.Status == "offered" || a.Status == "pending" || a.Status == "accepted" || a.Status == "in_progress" {
				if u.AssignedLaboratoryID != nil && (a.FromLocationID == *u.AssignedLaboratoryID || a.ToLocationID == *u.AssignedLaboratoryID) {
					if a.WorkerID == nil || (a.WorkerID != nil && *a.WorkerID == u.ID) {
						offers = append(offers, a)
					}
				}
			}
		}
		out["assignments"] = offers
	case "requester":
		reqs := s.st.ListRequestsByRequester(u.ID)
		samples := []*domain.Sample{}
		for _, req := range reqs {
			if smp, ok := s.st.GetSample(req.SampleID); ok {
				samples = append(samples, smp)
			}
		}
		out["requests"] = reqs
		out["samples"] = samples
	default:
		// dispatcher / admin: see everything
		out["assignments"] = s.st.ListAssignments()
		out["samples"] = s.st.AllSamples()
		out["requests"] = s.st.ListRequests()
		out["handoffs"] = s.st.ListHandoffs()
	}
	OK(w, out)
}

