import (
	"context"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"arena.local/lab/internal/api"
	"arena.local/lab/internal/auth"
	"arena.local/lab/internal/domain"
	"arena.local/lab/internal/seed"
	"arena.local/lab/internal/serviceability"
	"arena.local/lab/internal/store"

	"github.com/google/uuid"
	"github.com/redis/go-redis/v9"
	"go.mongodb.org/mongo-driver/v2/mongo"
	"go.mongodb.org/mongo-driver/v2/mongo/options"
)

func envOr(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	pgDSN := envOr("POSTGRES_DSN", "postgres://postgres:postgres@127.0.0.1:5432/postgres?sslmode=disable")
	mongoURI := envOr("MONGO_URI", "mongodb://127.0.0.1:27017")
	redisAddr := envOr("REDIS_ADDR", "127.0.0.1:6379")
	listenAddr := envOr("LISTEN_ADDR", "127.0.0.1:8080")

	pg, err := store.ConnectPG(ctx, pgDSN)
	if err != nil {
		log.Printf("postgres connect failed: %v", err)
		os.Exit(1)
	}
	defer pg.Close()

	if err := store.RunMigrations(ctx, pg); err != nil {
		log.Printf("migrations failed: %v", err)
		os.Exit(1)
	}

	rdb := redis.NewClient(&redis.Options{Addr: redisAddr})
	if err := rdb.Ping(ctx).Err(); err != nil {
		log.Printf("redis ping failed: %v", err)
		os.Exit(1)
	}

	mc, err := mongo.Connect(options.Client().ApplyURI(mongoURI))
	if err != nil {
		log.Printf("mongo connect failed: %v", err)
		os.Exit(1)
	}
	if err := mc.Ping(ctx, nil); err != nil {
		log.Printf("mongo ping failed: %v", err)
		os.Exit(1)
	}

	st := store.New(ctx, pg, rdb, mc)

	// Load existing data
	if err := st.LoadAllUsers(); err != nil {
		log.Printf("load users: %v", err)
	}
	if err := st.LoadAllSampleTypes(); err != nil {
		log.Printf("load sample types: %v", err)
	}
	if err := st.LoadAllLocations(); err != nil {
		log.Printf("load locations: %v", err)
	}
	if err := st.LoadAllConnections(); err != nil {
		log.Printf("load connections: %v", err)
	}
	if err := st.LoadAllAcceptances(); err != nil {
		log.Printf("load acceptances: %v", err)
	}
	if err := st.LoadAllRequests(); err != nil {
		log.Printf("load requests: %v", err)
	}
	if err := st.LoadAllSamples(); err != nil {
		log.Printf("load samples: %v", err)
	}
	if err := st.LoadAllJourneys(); err != nil {
		log.Printf("load journeys: %v", err)
	}
	if err := st.LoadAllAssignments(); err != nil {
		log.Printf("load assignments: %v", err)
	}
	if err := st.LoadAllHandoffs(); err != nil {
		log.Printf("load handoffs: %v", err)
	}
	if err := st.LoadAllReservations(); err != nil {
		log.Printf("load reservations: %v", err)
	}

	// Seed default data if first-time boot (no sample types)
	if len(st.AllSampleTypes()) == 0 {
		log.Printf("Seeding initial data...")
		seed.Seed(st)
	}

	// Ensure initial admin
	if len(st.AllUsers()) == 0 {
		username := envOr("ADMIN_USERNAME", "admin")
		password := envOr("ADMIN_PASSWORD", "admin")
		admin := &domain.User{
			ID:           uuid.New(),
			Username:     username,
			FullName:     "System Administrator",
			Roles:        []string{"administrator"},
			Active:       true,
			PasswordHash: auth.HashPassword(password, username),
			ActiveRole:   "administrator",
			Available:    true,
		}
		if err := st.CreateUser(admin); err != nil {
			log.Printf("create admin: %v", err)
		} else {
			log.Printf("Initial administrator created: %s", username)
		}
	}

	svc := serviceability.New(pg, st)
	srv := api.NewServer(st, rdb, svc)

	httpSrv := &http.Server{
		Addr:              listenAddr,
		Handler:           srv,
		ReadHeaderTimeout: 10 * time.Second,
	}

	// Handle signals
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, os.Interrupt, syscall.SIGTERM)

	go func() {
		<-sigCh
		log.Printf("shutting down...")
		cancel()
		ctx, cncl := context.WithTimeout(context.Background(), 5*time.Second)
		defer cncl()
		httpSrv.Shutdown(ctx)
	}()

	log.Printf("listening on %s", listenAddr)
	if err := httpSrv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Printf("listen: %v", err)
		os.Exit(1)
	}
}"}

